          const action = match[0].toLowerCase().startsWith("hide") ? "hide" : match[0].toLowerCase().startsWith("isolate") ? "isolate" : "highlight";
          const catMap = {
            wall: "Walls",
            walls: "Walls",
            "curtain wall": "Curtain Walls",
            "curtain walls": "Curtain Walls",
            slab: "Slabs",
            slabs: "Slabs",
            floor: "Floors",
            floors: "Floors",
            ceiling: "Ceilings",
            ceilings: "Ceilings",
            roof: "Roofs",
            roofs: "Roofs",
            door: "Doors",
            doors: "Doors",
            window: "Windows",
            windows: "Windows",
            opening: "Openings",
            openings: "Openings",
            furniture: "Furniture",
            lighting: "Lighting Fixtures",
            "lighting fixture": "Lighting Fixtures",
            "lighting fixtures": "Lighting Fixtures",
            stair: "Stairs",
            stairs: "Stairs",
            handrail: "Handrails",
            handrails: "Handrails",
            column: "Columns",
            columns: "Columns",
            beam: "Beams",
            beams: "Beams",
            plumbing: "Plumbing",
            room: "Rooms",
            rooms: "Rooms"
          };
          const catLabel = catMap[raw] ?? "Walls";
          window.dispatchEvent(new CustomEvent("pryzm-visibility-command", {
            // TODO(TASK-11)
            detail: { action, target: "type-in-category", value: catLabel, subType }
          }));
