const apartmentGenerativeStage = (input, ctx) => {
  const engine = selectEngine(ctx.manifest, ctx.input);
  return {
    ok: true,
    artifact: {
      engine,
      payload: {
        kind: "apartment-bridge",
        version: ctx.manifest.version,
        // The bridge does not actually generate a plan — it signals
        // the dispatch caller to delegate to the existing
        // `@pryzm/ai-host` workflow. A.4.b replaces this stub with
        // a real generator that produces the same `GenerateLayoutResult`
        // shape the old workflow returned.
        delegateTo: engine === "ai-workflow" ? "apartment-layout-generate" : "apartment-layout-deterministic",
        brief: input.brief.raw,
        site: input.site.snapshot
      }
    }
  };
};

const apartmentBimEmitStage = ({ plan }) => {
  const bridge = {
    type: "typology.apartment.bridge",
    payload: {
      note: "A.4.a bridge — delegate to legacy apartment-layout-execute",
      plan
    }
  };
  return { ok: true, artifact: [bridge] };
};

function buildApartmentTypologyPack() {
  return {
    manifest: APARTMENT_MANIFEST,
    stages: {
      generative: apartmentGenerativeStage,
      bimEmit: apartmentBimEmitStage
    }
  };
}

